"use strict";

// モンパッチ共通UI効果音 v2.63
// ゲーム本体で使用中の「決定」「キャンセル」と同じ音源を使用。
(() => {
  const DATA = {
    decision: 'data:audio/mpeg;base64,',
    cancel: 'data:audio/mpeg;base64,'
  };
  const BASE_VOL = { decision: 0.22, cancel: 0.20 };
  const LEVEL_SCALE = [0, 0.45, 0.72, 1];

  function getSeLevel() {
    const n = Number(localStorage.getItem("match3_se_level") ?? 3);
    return Math.max(0, Math.min(3, Number.isFinite(n) ? n : 3));
  }

  function play(kind) {
    const level = getSeLevel();
    if (level === 0 || !DATA[kind]) return;
    try {
      const a = new Audio(DATA[kind]);
      a.preload = "auto";
      a.volume = Math.max(0, Math.min(1, BASE_VOL[kind] * LEVEL_SCALE[level]));
      a.play().catch(() => {});
    } catch (_) {}
  }

  window.playUiDecision = () => play("decision");
  window.playUiCancel = () => play("cancel");

  const cancelIds = new Set([
    "battleAvatarRemove",
    "leaveRoomBtn",
    "singleTopBackBtn",
    "multiTopBackFixed",
    "battleReturnBtn"
  ]);

  function classify(el) {
    const explicit = el?.dataset?.uiSfx;
    if (explicit === "none" || explicit === "decision" || explicit === "cancel") return explicit;
    if (cancelIds.has(el.id)) return "cancel";
    const t = (el.textContent || "").trim();
    if (/戻る|キャンセル|終了|退出|解除/.test(t)) return "cancel";
    return "decision";
  }

  document.addEventListener("click", (e) => {
    const el = e.target.closest("button, a[href], [role='button']");
    if (!el || el.disabled || el.getAttribute("aria-disabled") === "true") return;
    const kind = classify(el);
    if (kind !== "none") play(kind);
  }, true);
})();
